package com.rustybank.legacy;

import com.rustybank.TellerTerminal;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;

public class LegacyTellerTerminal implements TellerTerminal {

    private final AccountStore store;

    public LegacyTellerTerminal(AccountStore store) {
        this.store = store;
    }

    @Override
    public void openAccount(String accountId) {
        store.add(accountId);
    }

    @Override
    public void deposit(String accountId, String amount) {
        Account a = store.find(accountId);
        BigInteger cents = MoneyUtil.parseAmount(amount);
        a.setCents(a.getCents().add(cents));
    }

    @Override
    public void withdraw(String accountId, String amount) {
        Account a = store.find(accountId);
        BigInteger cents = MoneyUtil.parseAmount(amount);
        if (cents.compareTo(a.getCents()) > 0) {
            throw new IllegalStateException("INSUFFICIENT FUNDS");
        }
        a.setCents(a.getCents().subtract(cents));
    }

    @Override
    public String balance(String accountId) {
        return MoneyUtil.format(store.find(accountId).getCents());
    }

    @Override
    public String postMonthlyInterest(String accountId, String annualRatePercent) {
        Account a = store.find(accountId);
        BigDecimal rate;
        try {
            rate = new BigDecimal(annualRatePercent.trim());
            if (rate.compareTo(BigDecimal.ZERO) <= 0) {
                throw new IllegalArgumentException("INVALID RATE");
            }
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("INVALID RATE");
        }
        BigInteger interest = new BigDecimal(a.getCents())
                .multiply(rate)
                .divide(new BigDecimal("1200"), 0, RoundingMode.HALF_UP)
                .toBigInteger();
        a.setCents(a.getCents().add(interest));
        return MoneyUtil.format(interest);
    }

    @Override
    public List<String> splitPayment(String fromAccountId, String amount, List<String> payeeIds) {
        if (payeeIds == null || payeeIds.isEmpty()) {
            throw new IllegalArgumentException("NO PAYEES");
        }
        Account from = store.find(fromAccountId);
        BigInteger totalCents = MoneyUtil.parseAmount(amount);

        List<Account> payees = new ArrayList<>();
        for (String id : payeeIds) {
            payees.add(store.find(id));
        }

        if (totalCents.compareTo(from.getCents()) > 0) {
            throw new IllegalStateException("INSUFFICIENT FUNDS");
        }

        BigInteger n = BigInteger.valueOf(payees.size());
        BigInteger share = totalCents.divide(n);
        int remainder = totalCents.remainder(n).intValue();

        from.setCents(from.getCents().subtract(totalCents));
        List<String> results = new ArrayList<>();
        for (int i = 0; i < payees.size(); i++) {
            BigInteger amountToPay = (i < remainder) ? share.add(BigInteger.ONE) : share;
            Account p = payees.get(i);
            p.setCents(p.getCents().add(amountToPay));
            results.add(MoneyUtil.format(amountToPay));
        }
        return results;
    }

    @Override
    public String totalHoldings() {
        BigInteger sum = BigInteger.ZERO;
        for (Account a : store.all()) {
            sum = sum.add(a.getCents());
        }
        return MoneyUtil.format(sum);
    }
}

