package com.rustybank.legacy;

import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.RoundingMode;

public class MoneyUtil {

    public static BigInteger parseAmount(String amount) {
        if (amount == null) {
            throw new IllegalArgumentException("INVALID AMOUNT");
        }
        try {
            BigDecimal d = new BigDecimal(amount.trim());
            if (d.compareTo(BigDecimal.ZERO) <= 0) {
                throw new IllegalArgumentException("INVALID AMOUNT: " + amount);
            }
            return d.movePointRight(2).setScale(0, RoundingMode.HALF_UP).toBigInteger();
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("INVALID AMOUNT: " + amount);
        }
    }

    public static String format(BigInteger cents) {
        return new BigDecimal(cents).movePointLeft(2).setScale(2, RoundingMode.UNNECESSARY).toPlainString();
    }
}

